method vowels_count(s: string) returns (count: int)
    // Precondition: The input string 's' can be any string, including empty strings
    requires s != null
    // Postcondition: The returned count is the number of vowels in the string.
    // Vowels are defined as 'a', 'e', 'i', 'o', 'u', and also 'y' only if it is the last character in the string.
    ensures count == CountVowels(s)
{
    // Implementation would go here
}

function CountVowels(s: string): int
    reads s
{
    var count := 0;
    var length := s.Length;

    // Count the vowels according to the specified rules
    for i := 0 to length - 1 {
        var ch := s[i].ToLower();
        if ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u' {
            count := count + 1;
        }
    }

    // Check if 'y' is the last character
    if length > 0 && s[length - 1].ToLower() == 'y' {
        count := count + 1;
    }

    return count;
}
